                reason: string;
                /** @description The refund paid out for this reversal (D8): for a `void`, one entry mirroring each collected sale tender (card to card, cash to cash); for a `return`, cash only (`RefundTender`). The amounts sum to the server-computed `refundableAmount` (the collected share, see `recordCreditSaleReversal`) exactly, else 422 `credit_reversal_refund_mismatch`; an empty list when that amount is 0 (a full-credit sale). Never the credit share. */
                refundTenders: components["schemas"]["CreditReversalRefundTender"][];
